/* ============================
   🔘 Global Button Styles
============================ */
button,
.btn {
  padding: 10px 18px;
  border-radius: 10px;
  font-weight: 600;
  font-size: 0.95rem;
  cursor: pointer;
  border: 1px solid #475569;
  background: #334155;
  color: #f8fafc;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  margin: 6px 4px;
  outline: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

/* ✨ Hover State: Radiant Indigo Glow */
button:hover,
.btn:hover {
  background-color: #4f46e5 !important;
  border-color: #818cf8 !important;
  color: #ffffff !important;
  box-shadow: 0 0 16px rgba(99, 102, 241, 0.5), 0 4px 12px rgba(0, 0, 0, 0.3) !important;
}

/* ⚡ Active State (When clicked): Darkened & Inset Pressed effect */
button:active,
.btn:active {
  transform: scale(0.94) !important;
  background-color: #312e81 !important;
  border-color: #4338ca !important;
  box-shadow: inset 0 3px 6px rgba(0, 0, 0, 0.5), 0 0 8px rgba(99, 102, 241, 0.2) !important;
}

/* ☀️ Light Mode Button Styles */
.page-light button,
.card-light button {
  background: #ffffff;
  color: #0f172a;
  border-color: #cbd5e1;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.05);
}

.page-light button:hover,
.card-light button:hover {
  background-color: #3b82f6 !important;
  color: #ffffff !important;
  border-color: #60a5fa !important;
  box-shadow: 0 0 16px rgba(59, 130, 246, 0.45) !important;
}

.page-light button:active,
.card-light button:active {
  background-color: #1d4ed8 !important;
  color: #ffffff !important;
  transform: scale(0.94) !important;
}

