@media (max-width: 640px) {
  .title {
    font-size: 2.25rem;
  }

  .cards-grid {
    grid-template-columns: 1fr;
  }
}

/* =========================================
   🦾 CYBERPUNK BOUNTY HQ DESIGN SYSTEM
========================================= */

.cyber-container {
  max-width: 680px;
  margin: 0 auto;
  padding: 32px 28px;
  border-radius: 20px;
  background: rgba(15, 23, 42, 0.92);
  border: 2px solid #334155;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.6);
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* 🕶️ Stealth Mode State: Emerald Matrix Glow */
.cyber-stealth {
  border-color: #10b981 !important;
  box-shadow: 0 0 35px rgba(16, 185, 129, 0.25), inset 0 0 20px rgba(16, 185, 129, 0.05) !important;
}

/* 🚨 Combat Mode State: Neon Crimson Warning Glow */
.cyber-combat {
  border-color: #f43f5e !important;
  box-shadow: 0 0 35px rgba(244, 63, 94, 0.3), inset 0 0 20px rgba(244, 63, 94, 0.06) !important;
}

/* 📊 HUD Stats Bar */
.hud-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  margin: 18px 0;
}

.hud-badge {
  background: #020617;
  border: 1.5px solid #38bdf8;
  color: #38bdf8;
  font-family: 'Courier New', Courier, monospace;
  font-size: 1.05rem;
  font-weight: 700;
  padding: 8px 18px;
  border-radius: 12px;
  box-shadow: 0 0 12px rgba(56, 189, 248, 0.2);
  letter-spacing: 0.05em;
}

/* 📋 Mission Card */
.cyber-card {
  background: #1e293b;
  border: 1.5px solid #334155;
  border-radius: 14px;
  padding: 18px 20px;
  margin-top: 14px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.3);
  transition: all 0.2s ease;
}

/* 🎯 Cyber Action Buttons */
.btn-complete {
  background-color: #059669 !important;
  border-color: #34d399 !important;
  color: #ffffff !important;
  box-shadow: 0 0 12px rgba(16, 185, 129, 0.35) !important;
}

.btn-complete:hover {
  background-color: #10b981 !important;
  box-shadow: 0 0 20px rgba(16, 185, 129, 0.6) !important;
}

.btn-abandon {
  background-color: #dc2626 !important;
  border-color: #f87171 !important;
  color: #ffffff !important;
  box-shadow: 0 0 12px rgba(239, 68, 68, 0.35) !important;
}

.btn-abandon:hover {
  background-color: #ef4444 !important;
  box-shadow: 0 0 20px rgba(239, 68, 68, 0.6) !important;
}

